// Big "+1,950 B" that pops up in the middle of the screen whenever a round pays more than its bet.
function WinAmountPop({ pop }) {
  const [shown, setShown] = useState(null);
  useEffect(() => {
    if (!pop) return;
    setShown(pop);
    const t = setTimeout(() => setShown(null), 2200);
    return () => clearTimeout(t);
  }, [pop]);
  if (!shown) return null;
  const big = shown.amount >= shown.wager * 10;
  return (
    <div key={shown.key} style={{ position: "fixed", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "none", zIndex: 9999 }}>
      <div style={{ textAlign: "center", animation: "winpop-in 2.2s cubic-bezier(.2,1.6,.4,1) forwards" }}>
        <div style={{ fontFamily: "Prompt,sans-serif", fontWeight: 800, fontSize: 22, color: "#fff", letterSpacing: 2, textShadow: "0 2px 10px rgba(0,0,0,.8)" }}>{big ? "BIG WIN!" : "ชนะ!"}</div>
        <div style={{
          fontFamily: "Prompt,sans-serif", fontWeight: 900, fontSize: "clamp(52px, 17vw, 110px)", lineHeight: 1.05,
          background: "linear-gradient(180deg,#fff6c9 0%,#f4c542 45%,#c98a0b 100%)", WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent",
          filter: "drop-shadow(0 4px 0 #6b4400) drop-shadow(0 0 22px rgba(244,197,66,.75))",
        }}>+{shown.amount.toLocaleString("th-TH", { maximumFractionDigits: 2 })}</div>
        <div style={{ fontFamily: "Prompt,sans-serif", fontWeight: 800, fontSize: 26, color: "#f4c542", textShadow: "0 2px 8px rgba(0,0,0,.8)" }}>B</div>
      </div>
    </div>
  );
}

function BigWinFlash({ tier, trigger }) {
  const [show, setShow] = useState(false);
  const firstRun = useRef(true);
  useEffect(() => {
    if (firstRun.current) { firstRun.current = false; return; }
    if (tier === "normal") return;
    setShow(true);
    const t = setTimeout(() => setShow(false), 1500);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [trigger]);

  if (!show || tier === "normal") return null;
  const label = tier === "mega" ? "MEGA WIN!" : "BIG WIN!";
  return (
    <div className="bigwin-flash">
      <div className={`bigwin-text ${tier}`}>{label}</div>
    </div>
  );
}

function GoldSparkles({ count = 14 }) {
  const sparks = useMemo(() => Array.from({ length: count }, (_, i) => ({
    id: i,
    left: Math.random() * 100,
    top: Math.random() * 100,
    size: 3 + Math.random() * 5,
    delay: Math.random() * 3,
    duration: 1.8 + Math.random() * 2.2,
    // eslint-disable-next-line react-hooks/exhaustive-deps
  })), [count]);
  return (
    <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 2 }}>
      {sparks.map((s) => (
        <span key={s.id} className="gold-sparkle" style={{
          left: `${s.left}%`, top: `${s.top}%`, width: s.size, height: s.size,
          animationDelay: `${s.delay}s`, animationDuration: `${s.duration}s`,
        }} />
      ))}
    </div>
  );
}

function DiceLandBurst({ trigger, count = 32 }) {
  const [show, setShow] = useState(false);
  const firstRun = useRef(true);
  const dust = useMemo(() => Array.from({ length: count }, (_, i) => {
    const angle = (i / count) * Math.PI * 2 + Math.random() * 0.5;
    const distX = 70 + Math.random() * 150;
    const distY = 50 + Math.random() * 100;
    return {
      id: i,
      dx: Math.cos(angle) * distX,
      dy: Math.sin(angle) * distY - 12,
      size: 2 + Math.random() * 5.5,
      delay: Math.random() * 0.1,
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [trigger, count]);

  useEffect(() => {
    if (firstRun.current) { firstRun.current = false; return; }
    setShow(true);
    const t = setTimeout(() => setShow(false), 1050);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [trigger]);

  if (!show) return null;
  return (
    <div style={{ position: "absolute", inset: 0, pointerEvents: "none", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1 }}>
      <div className="dice-land-glow" />
      {dust.map((p) => (
        <span key={p.id} className="dice-dust" style={{ "--dx": `${p.dx}px`, "--dy": `${p.dy}px`, width: p.size, height: p.size, animationDelay: `${p.delay}s` }} />
      ))}
    </div>
  );
}

