const CLASSIC_SYMBOLS = [
  { id: "cherry", label: "🍒", weight: 32, pay3: 2, pay2: 1 },
  { id: "lemon", label: "🍋", weight: 24, pay3: 3, pay2: 0 },
  { id: "bell", label: "🔔", weight: 16, pay3: 10, pay2: 0 },
  { id: "bar", label: "BAR", weight: 12, pay3: 25, pay2: 0 },
  { id: "seven", label: "7️⃣", weight: 6, pay3: 77, pay2: 0 },
];
const CLASSIC_POOL = CLASSIC_SYMBOLS.flatMap((s) => Array(s.weight).fill(s));
function classicSpinReel() { return CLASSIC_POOL[Math.floor(Math.random() * CLASSIC_POOL.length)]; }
// ---------- Jungle Riches (5x5 slot) ----------
const JUNGLE_SYMBOLS = [
  { id: "WILD", label: "WILD", sub: "เทพีป่า", glyph: "🐅", mult: 50, bg: "linear-gradient(155deg,#e8c766,#b8860b)", fg: "#1c1204" },
  { id: "SCATTER", label: "SCATTER", sub: "", glyph: "⭐", mult: 0, bg: "linear-gradient(155deg,#ef5350,#b71c1c)", fg: "#fff" },
  { id: "MASK", label: "หน้ากาก", sub: "ทองคำ", glyph: "🎭", mult: 20, bg: "linear-gradient(155deg,#d4af37,#8b6914)", fg: "#fff" },
  { id: "STATUE", label: "รูปปั้น", sub: "หินโบราณ", glyph: "🗿", mult: 15, bg: "linear-gradient(155deg,#26a69a,#00695c)", fg: "#fff" },
  { id: "A", label: "A", sub: "", glyph: "♠", mult: 10, bg: "linear-gradient(155deg,#e07a3f,#a1461f)", fg: "#fff" },
  { id: "K", label: "K", sub: "", glyph: "♥", mult: 8, bg: "linear-gradient(155deg,#9c6ade,#5e35b1)", fg: "#fff" },
  { id: "Q", label: "Q", sub: "", glyph: "♦", mult: 5, bg: "linear-gradient(155deg,#e0609e,#ad1457)", fg: "#fff" },
  { id: "J", label: "J", sub: "", glyph: "♣", mult: 3, bg: "linear-gradient(155deg,#5b8def,#1e4fc4)", fg: "#fff" },
  { id: "10", label: "10", sub: "", glyph: "♠", mult: 2, bg: "linear-gradient(155deg,#3fb6a8,#00695c)", fg: "#fff" },
];
const JUNGLE_ROWS = 5, JUNGLE_COLS = 5;
function jungleRandomSymbol() { return JUNGLE_SYMBOLS[Math.floor(Math.random() * JUNGLE_SYMBOLS.length)]; }
function jungleRandomGrid() {
  return Array.from({ length: JUNGLE_ROWS }, () => Array.from({ length: JUNGLE_COLS }, jungleRandomSymbol));
}
function jungleRowMatches(row) {
  const first = row[0];
  return row.every((item) => item.id === first.id || item.id === "WILD") && first.mult > 0;
}
// Win/lose is decided first by edges.jungle (the admin win rate). Instead of
// forcing a specific row (which would look repetitive), this just re-rolls
// genuinely random grids until one happens to land on the correct side of
// the decision - a real win-row match if won, none if lost - so every
// winning grid still looks naturally varied.
function jungleRandomGridForOutcome(won) {
  for (let attempt = 0; attempt < 3000; attempt++) {
    const grid = jungleRandomGrid();
    if (grid.some(jungleRowMatches) === won) return grid;
  }
  const grid = jungleRandomGrid();
  if (won) {
    const symbol = JUNGLE_SYMBOLS.find((s) => s.mult > 0) || JUNGLE_SYMBOLS[2];
    grid[0] = Array.from({ length: JUNGLE_COLS }, () => symbol);
  } else {
    grid.forEach((row) => { if (jungleRowMatches(row)) row[0] = { ...row[0], id: row[0].id + "_x" }; });
  }
  return grid;
}

