const CATEGORIES = [
  { id: "lobby", label: "ทั้งหมด", icon: "🏠" },
  { id: "originals", label: "เกมต้นฉบับ", icon: "🔥" },
  { id: "slots", label: "สล็อต", icon: "🎰" },
  { id: "cards", label: "ไพ่", icon: "🃏" },
  { id: "wheel", label: "วงล้อ", icon: "🎡" },
  { id: "popular", label: "ยอดนิยม", icon: "⭐" },
  { id: "new", label: "เกมใหม่", icon: "🆕" },
  { id: "lottery", label: "หวย", icon: "🎟️" },
];
// "cards"/"wheel" filter by each game's real icon field, "popular" by live
// player count, "new" by the same tag already used for the card badge -
// all derived from data the catalog already has, nothing fabricated.
function gamesForCategory(games, catId, counts) {
  if (catId === "lobby") return games;
  if (catId === "cards") return games.filter((g) => g.icon === "cards");
  if (catId === "wheel") return games.filter((g) => g.icon === "wheel");
  if (catId === "new") return games.filter((g) => g.tag === "ใหม่");
  if (catId === "popular") {
    return [...games].sort((a, b) => (counts?.[b.id] || b.base) - (counts?.[a.id] || a.base)).slice(0, 8);
  }
  return games.filter((g) => g.cat === catId);
}

function useLiveCounts(games) {
  const [counts, setCounts] = useState(() => Object.fromEntries(games.map((g) => [g.id, g.base])));
  useEffect(() => {
    const t = setInterval(() => setCounts((prev) => {
      const next = { ...prev };
      games.forEach((g) => { const drift = Math.floor(Math.random() * 9) - 4; next[g.id] = Math.max(40, prev[g.id] + drift); });
      return next;
    }), 2200);
    return () => clearInterval(t);
  }, [games]);
  return counts;
}

function CardTrack({ games, counts, onOpenGame }) {
  const trackRef = useRef(null);
  function scroll(dir) {
    trackRef.current?.scrollBy({ left: dir * 340, behavior: "smooth" });
  }
  if (!games.length) return null;
  return (
    <div style={{ position: "relative" }}>
      <div className="card-track" ref={trackRef}>
        {games.map((g) => {
          const playable = PLAYABLE[g.id];
          return (
            <div className="card-col" key={g.id}>
              <button className="game-card" style={{ background: g.img ? "#000" : `linear-gradient(155deg,${g.grad[0]},${g.grad[1]})` }}
                onClick={() => playable && onOpenGame(playable)}>
                {g.img ? (
                  g.imgFit === "contain" ? (<>
                    <img src={g.img} alt="" aria-hidden="true" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", filter: "blur(14px) brightness(0.55)", transform: "scale(1.15)" }} />
                    <img src={g.img} alt={g.name} style={{ position: "absolute", left: 0, right: 0, top: "50%", transform: "translateY(-50%)", width: "100%", height: "auto" }} />
                  </>) : (
                  <img src={g.img} alt={g.name} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
                  )
                ) : (
                  <>
                    <div className="art">{ICONS[g.icon]}</div>
                    <div className="overlay">
                      <div className="name">{g.name}</div>
                      <div className="tagline">WINNER 69 {playable ? "· เล่นได้" : ""}</div>
                    </div>
                  </>
                )}
                {playable && <span className="play-badge">เล่นได้</span>}
              </button>
              <div className="card-meta"><span className="dot" />{counts[g.id]?.toLocaleString()} กำลังเล่น</div>
            </div>
          );
        })}
      </div>
      <div className="scroll-arrows" style={{ position: "absolute", top: -40, right: 0 }}>
        <button className="scroll-arrow" onClick={() => scroll(-1)}>←</button>
        <button className="scroll-arrow" onClick={() => scroll(1)}>→</button>
      </div>
    </div>
  );
}

function BannerIcon({ emoji, bg }) {
  return <div className="banner-icon" style={{ background: bg }}>{emoji}</div>;
}

function WithdrawTicker({ notifications, wins }) {
  // "Live activity" ticker - merges real approved withdrawals with a
  // separate, purely-decorative simulated-wins feed (see Lobby). Everything
  // shown here is either a real approved transaction or clearly-labeled
  // demo data generated client-side; nothing here is invented as if it
  // were a genuine unapproved transaction.
  const withdrawItems = (notifications || []).map((n) => ({ id: `wd-${n.id}`, kind: "withdraw", username: n.username, amount: n.amount, time: n.time }));
  const winItems = (wins || []).map((w) => ({ id: `win-${w.id}`, kind: "win", username: w.username, amount: w.amount, time: w.time }));
  const merged = [...withdrawItems, ...winItems].sort((a, b) => a.time - b.time);

  if (merged.length === 0) {
    const placeholder = "ยังไม่มีกิจกรรมในเซสชันนี้ — พอมีสมาชิกถอนเครดิตหรือชนะเกมจริง รายการจะขึ้นแสดงที่นี่แบบเลื่อนอัตโนมัติ";
    return (
      <div className="withdraw-ticker">
        <div className="withdraw-ticker-track">
          {[0, 1].map((i) => (
            <span className="withdraw-chip withdraw-chip-muted" key={i}>{placeholder}</span>
          ))}
        </div>
      </div>
    );
  }
  const items = merged.slice(-20);
  const track = [...items, ...items]; // duplicate for seamless loop
  return (
    <div className="withdraw-ticker">
      <div className="withdraw-ticker-track">
        {track.map((n, i) => (
          <span className="withdraw-chip" key={`${n.id}-${i}`}>
            🟢 👤 <b>{n.username}</b>{" "}
            {n.kind === "win" ? (
              <>ชนะ <b>{n.amount.toLocaleString()} B</b> <span className="withdraw-ok">🎉</span></>
            ) : (
              <>ถอน <b>{n.amount.toLocaleString()} B</b> <span className="withdraw-ok">ถอนสำเร็จ ✅</span></>
            )}
          </span>
        ))}
      </div>
    </div>
  );
}

// Matches the reference's 5-item layout (หน้าหลัก / เกม / กระเป๋า / กิจกรรม / โปรไฟล์)
// with กระเป๋า as the elevated center action. Shop and Admin access aren't
// dropped - per "keep all existing functionality working" - they've moved
// into the header's ⚙️ settings menu (LobbyHeader) and the hero carousel's
// shop slide instead of taking two of the five primary slots.
function BottomNav({ active, onShop, onProfile, onChat, onLottery }) {
  const { chatThreads, currentUser } = useApp();
  const unreadFromAdmin = currentUser ? (chatThreads[currentUser] || []).filter((m) => m.from === "admin" && !m.read).length : 0;
  const items = [
    { id: "home", label: "หน้าหลัก", onClick: () => window.scrollTo({ top: 0, behavior: "smooth" }) },
    { id: "chat", label: "แชท", onClick: onChat, badge: unreadFromAdmin },
    { id: "shop", label: "ไอเทมบูสต์", onClick: onShop },
    { id: "lottery", label: "หวย", onClick: onLottery || (() => window.scrollTo({ top: 0, behavior: "smooth" })) },
    { id: "profile", label: "โปรไฟล์", onClick: onProfile },
  ];
  return (
    <nav className="tabbar">
      <div className="tabbar-inner">
        {items.map((it) => (
          <button key={it.id} className={`tabbar-item${active === it.id ? " active" : ""}`} onClick={it.onClick}>
            <span className="tabbar-label">{it.label}</span>
            {it.badge > 0 && <span className="tabbar-badge">{it.badge > 99 ? "99+" : it.badge}</span>}
          </button>
        ))}
      </div>
    </nav>
  );
}

// ---------- Language selector (9 flags, UI-level only) ----------
// NOTE: this switches which flag is shown/selected and persists the choice,
// but does not machine-translate the rest of the app's copy into all nine
// languages - that would need a full i18n pass across every component.
// Thai stays the default and primary language everywhere else in the UI.
const LANGUAGES = [
  { code: "th", flag: "🇹🇭", label: "ไทย" },
  { code: "en", flag: "🇬🇧", label: "English" },
  { code: "zh", flag: "🇨🇳", label: "中文" },
  { code: "ja", flag: "🇯🇵", label: "日本語" },
  { code: "ko", flag: "🇰🇷", label: "한국어" },
  { code: "vi", flag: "🇻🇳", label: "Tiếng Việt" },
  { code: "my", flag: "🇲🇲", label: "မြန်မာ" },
  { code: "lo", flag: "🇱🇦", label: "ລາວ" },
  { code: "km", flag: "🇰🇭", label: "ខ្មែរ" },
];

function LanguageSelector() {
  const [open, setOpen] = useState(false);
  const [lang, setLang] = useState(() => {
    try { return localStorage.getItem("winner69_lang") || "th"; } catch (e) { return "th"; }
  });
  useEffect(() => {
    try { localStorage.setItem("winner69_lang", lang); } catch (e) {}
  }, [lang]);
  const current = LANGUAGES.find((l) => l.code === lang) || LANGUAGES[0];
  return (
    <div style={{ position: "relative" }}>
      <button onClick={() => setOpen((o) => !o)} title="เลือกเซิร์ฟเวอร์ประเทศ" className="lang-trigger-btn">
        {current.flag} <span>Server {current.label}</span> <span className="lang-caret">▼</span>
      </button>
      {open && (
        <>
          <div onClick={() => setOpen(false)} className="dropdown-backdrop" />
          <div className="lang-dropdown">
            {LANGUAGES.map((l) => (
              <button key={l.code} onClick={() => { setLang(l.code); setOpen(false); }}
                className={`lang-option${l.code === lang ? " active" : ""}`}>
                <span style={{ fontSize: 16 }}>{l.flag}</span>{l.label}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ---------- VIP tier (derived from real session wagering, not fabricated) ----------
function deriveVipTier(wagered) {
  return Math.min(10, 1 + Math.floor((wagered || 0) / 500));
}

// ---------- Lobby header: avatar/VIP/balance, centered brand, bell + settings + language ----------
function LobbyHeader({ username, onLogout, onAdmin, onShop, balance }) {
  const { notifications, userStats, muted, toggleMuted } = useApp();
  const [bellOpen, setBellOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const wagered = userStats[username]?.wagered || 0;
  const vipTier = deriveVipTier(wagered);
  // The gold VIP crown is a balance-based perk, not a session-activity one:
  // members with at least 1,000 B in their account get the crown badge;
  // below that they see a plain "สมาชิก" (member) label instead.
  const isVip = balance >= 1000;
  const myNotifs = notifications.filter((n) => n.username === username).slice(0, 8);
  const myPending = myNotifs.filter((n) => n.status === "pending").length;

  return (
    <div className="lobby-header">
      <div className="lobby-header-bg" style={{ backgroundImage: `url(${IMG_HEADER_BG})` }} />
      <div className="lobby-header-row">
        <div className="lobby-header-left">
          <div className="lobby-avatar">
            <img src={BRAND_LOGO} alt={username} style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "inherit" }} />
          </div>
          <div>
            <div className="lobby-username">{username}</div>
            {isVip ? (
              <div className="lobby-vip"><span className="lobby-vip-crown">👑</span> VIP Rank {vipTier}</div>
            ) : (
              <div className="lobby-member">สมาชิก</div>
            )}
            <div className="lobby-mini-balance">💰 {balance.toLocaleString(undefined, { maximumFractionDigits: 2 })} B</div>
          </div>
        </div>
        <div className="lobby-header-right">
          <LanguageSelector />
          <div style={{ position: "relative" }}>
            <button onClick={() => setBellOpen((o) => !o)} title="การแจ้งเตือน" className="icon-circle-btn">
              🔔
              {myPending > 0 && <span className="notif-dot">{myPending}</span>}
            </button>
            {bellOpen && (
              <>
                <div onClick={() => setBellOpen(false)} className="dropdown-backdrop" />
                <div className="bell-dropdown">
                  <div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 6 }}>คำขอถอนของฉัน</div>
                  {myNotifs.length === 0 ? (
                    <div style={{ fontSize: 12, color: "var(--muted)" }}>ยังไม่มีรายการ</div>
                  ) : myNotifs.map((n) => (
                    <div key={n.id} style={{ fontSize: 12, padding: "6px 0", borderBottom: "1px solid var(--line)" }}>
                      ถอน {n.amount.toLocaleString()} B — {n.status === "pending" ? "⏳ รอตรวจสอบ" : n.status === "approved" ? "✅ อนุมัติแล้ว" : "❌ ปฏิเสธ"}
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
          <div style={{ position: "relative" }}>
            <button onClick={() => setMenuOpen((o) => !o)} title="การตั้งค่า" className="icon-circle-btn">⚙️</button>
            {menuOpen && (
              <>
                <div onClick={() => setMenuOpen(false)} className="dropdown-backdrop" />
                <div className="bell-dropdown">
                  <button className="settings-menu-item" onClick={() => { toggleMuted(); setMenuOpen(false); }}>{muted ? "🔇 เปิดเสียง" : "🔊 ปิดเสียง"}</button>
                  {onShop && <button className="settings-menu-item" onClick={() => { setMenuOpen(false); onShop(); }}>🧪 ไอเทมบูสต์</button>}
                  {onAdmin && <button className="settings-menu-item" onClick={() => { setMenuOpen(false); onAdmin(); }}>⚙️ หน้าแอดมิน</button>}
                  <button className="settings-menu-item" style={{ color: "var(--red)" }} onClick={() => { setMenuOpen(false); onLogout(); }}>🚪 ออกจากระบบ</button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

