// ---------- Hero promotion carousel (swipe + arrows + autoplay + dots) ----------
function HeroCarousel({ onLeaderboard, onShop, onWallet, onOpenGame }) {
  // Real promotional banner images (provided by the user), full-bleed per
  // slide - the artwork already contains its own headline/CTA text, so no
  // text overlay is rendered on top of these.
  const slides = [
    { key: "boost-promo", img: IMG_BANNER1, alt: "ซื้อไอเทมบูสต์ 2 ครั้ง 50 บาท", onClick: onShop },
    { key: "welcome-bonus", img: IMG_BANNER2, alt: "โบนัสต้อนรับสมาชิกใหม่", onClick: onWallet },
    { key: "clawgame-promo", img: IMG_BANNER3, alt: "เกมตู้คีบตุ๊กตาให้โชค", onClick: () => onOpenGame(PLAYABLE.plushieparadise) },
  ];

  const [index, setIndex] = useState(0);
  const dragState = useRef(null);

  useEffect(() => {
    const t = setInterval(() => setIndex((i) => (i + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, [slides.length]);

  function goTo(i) { setIndex(((i % slides.length) + slides.length) % slides.length); }
  function onPointerDown(e) { dragState.current = { startX: (e.touches ? e.touches[0].clientX : e.clientX) }; }
  function onPointerUp(e) {
    if (!dragState.current) return;
    const endX = e.changedTouches ? e.changedTouches[0].clientX : e.clientX;
    const dx = endX - dragState.current.startX;
    if (dx > 40) goTo(index - 1);
    else if (dx < -40) goTo(index + 1);
    dragState.current = null;
  }

  return (
    <div className="hero-carousel">
      <div className="hero-track" style={{ transform: `translateX(-${index * 100}%)` }}
        onTouchStart={onPointerDown} onTouchEnd={onPointerUp}
        onMouseDown={onPointerDown} onMouseUp={onPointerUp}>
        {slides.map((s) => (
          <button className="hero-slide hero-slide-img" key={s.key} onClick={s.onClick} aria-label={s.alt}>
            <img src={s.img} alt={s.alt} className="hero-slide-image" />
          </button>
        ))}
      </div>
      {slides.length > 1 && (
        <>
          <button className="hero-arrow left" onClick={() => goTo(index - 1)} aria-label="ก่อนหน้า">‹</button>
          <button className="hero-arrow right" onClick={() => goTo(index + 1)} aria-label="ถัดไป">›</button>
          <div className="hero-dots">
            {slides.map((s, i) => <button key={s.key} className={`hero-dot${i === index ? " active" : ""}`} onClick={() => goTo(i)} aria-label={`สไลด์ ${i + 1}`} />)}
          </div>
        </>
      )}
    </div>
  );
}

// ---------- Weekly tournament teaser (real data - reuses the same ranking the Leaderboard page computes) ----------
const RANK_MEDALS = ["🥇", "🥈", "🥉"];

function TournamentCard({ onLeaderboard }) {
  const { users, userStats } = useApp();
  const top3 = useMemo(() => {
    const realRows = Object.keys(users).map((name) => {
      const s = userStats[name] || { rounds: 0, wagered: 0, payout: 0 };
      return { name, net: s.payout - s.wagered, rounds: s.rounds };
    }).filter((r) => r.rounds > 0);
    const fillers = makeLeaderboardFillers(new Set(Object.keys(users)), Math.max(0, 3 - realRows.length));
    const combined = [...realRows, ...fillers].sort((a, b) => b.net - a.net);
    return combined.slice(0, 3);
  }, [users, userStats]);

  if (top3.length === 0) return null;
  return (
    <div className="tournament-card">
      <div className="tournament-row-top">
        <div className="tournament-head"><span>🏆</span>ทัวร์นาเมนต์ประจำวัน</div>
        <button className="tournament-btn" onClick={onLeaderboard}>เข้าร่วม</button>
      </div>
      {top3.map((p, i) => (
        <div className="tournament-body" key={p.name + i}>
          <span className="tournament-rank">{RANK_MEDALS[i]} อันดับ {i + 1}</span>
          <span className="tournament-sep">·</span>
          <span className="tournament-player">{p.name}</span>
          <span className="tournament-sep">·</span>
          <span className="tournament-prize">+{Math.max(0, p.net).toLocaleString(undefined, { maximumFractionDigits: 2 })} B</span>
        </div>
      ))}
    </div>
  );
}


