function Lobby({ onOpenGame, onWallet, onAdmin, username, onLogout, onProfile, onShop, onLeaderboard, onChat }) {
  const { balance, notifications, simulatedWithdrawals, pushSimulatedWithdraw, users, userStats } = useApp();
  const [simulatedWins, setSimulatedWins] = useState([]);

  // Keep the "recent withdrawals" ticker spinning on its own with randomized
  // amounts, instead of relying on a manual seed button. Runs only while the
  // Lobby is mounted.
  useEffect(() => {
    const names = [
      "player1", "player2", "mookmik99", "beer_lucky", "somchai_vip", "aomsin_ch",
      "kong999", "fah_princess", "ta_masterx", "arm_bigwin", "pla_golden",
      "May_sabuy", "Peter_rich", "Nueng_go", "Ploy_lucky7",
    ];
    function pushRandom() {
      const name = names[Math.floor(Math.random() * names.length)];
      const amount = Math.round((300 + Math.random() * 94700) / 50) * 50;
      pushSimulatedWithdraw(name, amount);
    }
    pushRandom();
    const id = setInterval(pushRandom, 4000 + Math.random() * 3000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // A second, purely local "live activity" feed for simulated wins - kept
  // entirely separate from the real `notifications` withdrawal-approval
  // queue so it can never pollute what the admin panel needs to act on.
  // Demo/mock data only, per the reference spec's own instruction to keep
  // it clearly non-transactional.
  useEffect(() => {
    const names = [
      "player1", "player2", "mookmik99", "beer_lucky", "somchai_vip", "aomsin_ch",
      "kong999", "fah_princess", "ta_masterx", "arm_bigwin", "pla_golden",
      "May_sabuy", "Peter_rich", "Nueng_go", "Ploy_lucky7",
    ];
    function pushRandomWin() {
      const name = names[Math.floor(Math.random() * names.length)];
      const amount = Math.round((150 + Math.random() * 3800) / 10) * 10;
      setSimulatedWins((w) => [{ id: Date.now() + Math.random(), username: name, amount, time: Date.now() }, ...w].slice(0, 20));
    }
    pushRandomWin();
    const id = setInterval(pushRandomWin, 5000 + Math.random() * 3500);
    return () => clearInterval(id);
  }, []);
  const [category, setCategory] = useState("lobby");
  const [query, setQuery] = useState("");
  const counts = useLiveCounts(GAMES);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return GAMES.filter((g) => (q ? g.name.toLowerCase().includes(q) : true));
  }, [query]);
  const byCat = (cat) => gamesForCategory(filtered, cat, counts);
  const activeCat = CATEGORIES.find((c) => c.id === category);
  const playableOnly = (list) => list.filter((g) => PLAYABLE[g.id]);
  const gridGames = playableOnly(byCat(category));
  // HOT badge = the 3 most-played games by the catalog's base popularity (stable, no flicker)
  const hotIds = useMemo(() => new Set([...GAMES].sort((a, b) => b.base - a.base).slice(0, 3).map((g) => g.id)), []);
  const popularGames = useMemo(() => playableOnly([...GAMES].sort((a, b) => b.base - a.base)).slice(0, 10), []); // eslint-disable-line react-hooks/exhaustive-deps
  const newGames = useMemo(() => playableOnly(GAMES.filter((g) => g.tag === "ใหม่")), []); // eslint-disable-line react-hooks/exhaustive-deps

  function Section({ title, icon, games }) {
    if (!games.length) return null;
    return (
      <section className="section">
        <div className="section-head">
          <h2 className="section-title"><span>{icon}</span>{title}</h2>
        </div>
        <CardTrack games={games} counts={counts} onOpenGame={onOpenGame} />
      </section>
    );
  }

  return (
    <>
    <div aria-hidden="true" className="dragon-bg" style={{ "--cloud-pattern": `url("${CLOUD_SVG}")` }} />
    <div className="wrap-820" style={{ paddingBottom: 84, position: "relative", zIndex: 1 }}>
      <LobbyHeader username={username} onLogout={onLogout} onAdmin={onAdmin} onShop={onShop} balance={balance} />

      <WithdrawTicker notifications={[...notifications.filter((n) => n.status === "approved"), ...simulatedWithdrawals].sort((a, b) => b.time - a.time).slice(0, 30)} wins={simulatedWins} />

      <WalletCard balance={balance} onWallet={onWallet} />

      <TournamentCard onLeaderboard={onLeaderboard} />

      {(() => {
        const limit = users[username]?.wagerLimit || 0;
        if (limit <= 0) return null;
        const wagered = userStats[username]?.wagered || 0;
        const pct = Math.min(100, (wagered / limit) * 100);
        if (pct < 80) return null;
        return (
          <div style={{
            maxWidth: 920, margin: "0 auto 14px", padding: "10px 14px", borderRadius: 10, fontSize: 12,
            background: pct >= 100 ? "rgba(239,83,80,0.14)" : "rgba(232,199,102,0.14)",
            border: `1px solid ${pct >= 100 ? "var(--red)" : "var(--gold)"}`,
            color: pct >= 100 ? "var(--red)" : "var(--gold2)",
          }}>
            🛡️ {pct >= 100
              ? `คุณใช้วงเงินเดิมพันที่ตั้งไว้ครบแล้ว (${wagered.toLocaleString()} / ${limit.toLocaleString()} B) — พิจารณาพักการเล่น`
              : `ใช้วงเงินเดิมพันไปแล้ว ${pct.toFixed(0)}% (${wagered.toLocaleString()} / ${limit.toLocaleString()} B)`}
          </div>
        );
      })()}

      <HeroCarousel onLeaderboard={onLeaderboard} onShop={onShop} onWallet={onWallet} onOpenGame={onOpenGame} />

      <div className="dragon-filter">
        <div className="dragon-cats" role="tablist">
          {CATEGORIES.map((c) => (
            <button key={c.id} role="tab" aria-selected={category === c.id} className={`dragon-cat${category === c.id ? " active" : ""}`}
              onClick={() => { setCategory(c.id); document.getElementById("game-grid-section")?.scrollIntoView({ behavior: "smooth", block: "start" }); }}>
              <span className="ic">{c.icon}</span>{c.label}
            </button>
          ))}
        </div>
        <label className="dragon-search">
          <span aria-hidden="true">🔍</span>
          <input placeholder="ค้นหาเกม..." value={query} onChange={(e) => setQuery(e.target.value)} />
          {query && <button type="button" onClick={() => setQuery("")} style={{ background: "none", border: "none", color: "var(--muted)", cursor: "pointer", fontSize: 14 }} aria-label="ล้างคำค้น">✕</button>}
        </label>
      </div>

      {category === "lobby" && !query.trim() && (<>
        <DragonTitle icon="🔥" title="เกมยอดนิยม" />
        <div className="gt-track">
          {popularGames.map((g) => <GameTile key={g.id} g={g} hot={hotIds.has(g.id)} onOpenGame={onOpenGame} />)}
        </div>
        {newGames.length > 0 && (<>
          <DragonTitle icon="🧧" title="เกมใหม่" />
          <div className="gt-track">
            {newGames.map((g) => <GameTile key={g.id} g={g} hot={hotIds.has(g.id)} onOpenGame={onOpenGame} />)}
          </div>
        </>)}
      </>)}

      <section id="game-grid-section" style={{ marginBottom: 6, scrollMarginTop: 150 }}>
        <DragonTitle icon={activeCat?.icon || "🐉"} title={query.trim() ? `ผลการค้นหา "${query.trim()}"` : category === "lobby" ? "เกมทั้งหมด" : activeCat?.label} count={gridGames.length} />
        {gridGames.length === 0 ? <div className="gt-empty">ไม่พบเกมที่ค้นหา</div> : (
          <div className="gt-grid">
            {gridGames.map((g) => <GameTile key={g.id} g={g} hot={hotIds.has(g.id)} onOpenGame={onOpenGame} />)}
          </div>
        )}
      </section>

      <BottomNav
        onLottery={() => onOpenGame(PLAYABLE.lottery)}
        active="home"
        onShop={onShop}
        onProfile={onProfile}
        onChat={onChat}
      />
    </div>
    </>
  );
}


// ---------- Support Chat ----------
function readImageFile(file, cb) {
  if (!file) return;
  if (file.size > 4 * 1024 * 1024) { alert("ไฟล์รูปใหญ่เกินไป (จำกัด 4MB)"); return; }
  const reader = new FileReader();
  reader.onload = () => cb(reader.result);
  reader.readAsDataURL(file);
}

function ChatBubble({ msg, viewerIsAdmin }) {
  const mine = viewerIsAdmin ? msg.from === "admin" : msg.from === "user";
  return (
    <div style={{ display: "flex", justifyContent: mine ? "flex-end" : "flex-start", marginBottom: 10 }}>
      <div style={{
        maxWidth: "78%", padding: "8px 12px", borderRadius: 12, fontSize: 13,
        background: mine ? "var(--gold2)" : "var(--surface-2)",
        color: mine ? "#241203" : "var(--text)",
        border: mine ? "none" : "1px solid var(--line)",
      }}>
        {!mine && <div style={{ fontSize: 10.5, color: "var(--muted)", marginBottom: 3 }}>{viewerIsAdmin ? "สมาชิก" : "แอดมิน"}</div>}
        {msg.image && (
          <img src={msg.image} alt="แนบรูป" style={{ maxWidth: "100%", borderRadius: 8, marginBottom: msg.text ? 6 : 0, display: "block" }} />
        )}
        {msg.text && <div style={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>{msg.text}</div>}
        <div style={{ fontSize: 9.5, opacity: 0.6, marginTop: 4, textAlign: "right" }}>{timeAgo(msg.time)}</div>
      </div>
    </div>
  );
}

function ChatPage({ onBack, username }) {
  const { chatThreads, sendUserChatMessage, markChatRead } = useApp();
  const [text, setText] = useState("");
  const [pendingImage, setPendingImage] = useState(null);
  const fileInputRef = useRef(null);
  const scrollRef = useRef(null);
  const messages = chatThreads[username] || [];

  const unreadHere = messages.filter((m) => m.from === "admin" && !m.read).length;
  useEffect(() => {
    // opening the page, or a new reply arriving while it is open, counts as read
    if (username && (unreadHere > 0 || messages.length === 0)) markChatRead(username, "admin");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unreadHere]);
  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [messages.length]);

  // Defensive fallback: chat requires a logged-in member. Normally the
  // Lobby's chat button is gated behind login before this page is even
  // reached, but guard here too in case this is ever opened without one.
  if (!username) {
    return (
      <div className="game-wrap">
        <TopBar onBack={onBack} />
        <div className="panel" style={{ maxWidth: 420, textAlign: "center" }}>
          กรุณาเข้าสู่ระบบก่อนใช้งานแชท
        </div>
      </div>
    );
  }

  function handleFilePick(e) {
    readImageFile(e.target.files?.[0], setPendingImage);
    e.target.value = "";
  }
  function handleSend() {
    if (!text.trim() && !pendingImage) return;
    sendUserChatMessage(text, pendingImage);
    setText("");
    setPendingImage(null);
  }

  return (
    <div className="game-wrap">
      <TopBar onBack={onBack} />
      <div style={{ textAlign: "center", marginBottom: 10 }}>
        <div className="top-name" style={{ fontSize: 18 }}>💬 แชทติดต่อแอดมิน</div>
        <div style={{ fontSize: 11, color: "var(--muted)" }}>ส่งข้อความหรือแนบรูปภาพถึงแอดมินได้โดยตรง</div>
      </div>

      <div className="panel" style={{ maxWidth: 480, display: "flex", flexDirection: "column", height: "56vh", minHeight: 320 }}>
        <div ref={scrollRef} style={{ flex: 1, overflowY: "auto", padding: "4px 2px", marginBottom: 10 }}>
          {messages.length === 0 ? (
            <div style={{ textAlign: "center", color: "var(--muted)", fontSize: 12, marginTop: 30 }}>
              ยังไม่มีข้อความ — พิมพ์หรือแนบรูปเพื่อเริ่มสนทนากับแอดมินได้เลย
            </div>
          ) : messages.map((m) => <ChatBubble key={m.id} msg={m} />)}
        </div>

        {pendingImage && (
          <div style={{ position: "relative", marginBottom: 8, width: 84 }}>
            <img src={pendingImage} alt="พรีวิว" style={{ width: 84, height: 84, objectFit: "cover", borderRadius: 8, border: "1px solid var(--line)" }} />
            <button onClick={() => setPendingImage(null)}
              style={{ position: "absolute", top: -6, right: -6, width: 20, height: 20, borderRadius: "50%", background: "var(--red)", color: "#fff", border: "none", fontSize: 12, cursor: "pointer" }}>✕</button>
          </div>
        )}

        <div className="field-row" style={{ gap: 8 }}>
          <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFilePick} style={{ display: "none" }} />
          <button className="chip-btn" onClick={() => fileInputRef.current?.click()} title="แนบรูปภาพ" style={{ flexShrink: 0 }}>📎</button>
          <input className="field-input" style={{ flex: 1 }} placeholder="พิมพ์ข้อความ..." value={text}
            onChange={(e) => setText(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") handleSend(); }} />
          <button className="primary-btn" style={{ flexShrink: 0, padding: "10px 16px" }} onClick={handleSend}>ส่ง</button>
        </div>
      </div>
    </div>
  );
}

