        if (typeof window !== "undefined") window.alert("บันทึกไปที่เซิร์ฟเวอร์ไม่สำเร็จ (" + e.message + ") — ตรวจว่าเข้าแอดมินด้วยรหัสที่ถูกต้อง แล้วลองอีกครั้ง");
